def actor(name, coat, hair, style, expression='neutral'):
    im=Image.new('RGBA',(420,660));d=ImageDraw.Draw(im)
    d.ellipse((100,615,325,651),fill=(22,22,38,60))
    d.polygon((155,460,200,460,194,615,142,615),fill='#30344b');d.polygon((220,460,262,460,290,615,233,615),fill='#30344b')
    d.rounded_rectangle((130,603,198,635),12,fill='#232839');d.rounded_rectangle((228,603,300,635),12,fill='#232839')
    if style=='cape':d.polygon((143,217,275,217,358,530,66,530),fill=coat)
    else:d.polygon((142,218,278,218,310,475,111,475),fill=coat)
    d.polygon((143,230,105,250,66,424,104,438,170,278),fill=coat);d.polygon((275,230,310,247,350,424,315,438,250,278),fill=coat)
    d.ellipse((68,413,106,453),fill='#e7bc9b');d.ellipse((313,412,349,452),fill='#e7bc9b')
    d.rectangle((185,188,236,240),fill='#dba587');d.ellipse((145,62,274,205),fill=hair)
    d.ellipse((155,86,264,210),fill='#efc4a4');d.polygon((146,116,155,70,249,57,279,123,232,100,202,124,179,102),fill=hair)
    for x in (180,237):
        if expression=='joy':d.arc((x-10,143,x+10,158),180,360,fill='#323344',width=4)
        else:d.ellipse((x-5,143,x+5,155),fill='#323344')
    if expression=='joy':d.arc((186,160,231,187),0,180,fill='#8f4956',width=5)
    elif expression=='stern':d.line((194,177,225,175),fill='#8f4956',width=4);d.line((165,135,193,141),fill='#323344',width=4)
    else:d.line((198,177,222,177),fill='#8f4956',width=3)
    d.polygon((178,220,210,251,240,218,223,290,197,290),fill='#f7df9b');d.rectangle((119,405,298,423),fill='#533846')
    if style=='hat':d.polygon((122,91,196,4,288,92),fill=coat);d.ellipse((117,79,298,111),fill=coat)
    if style=='cape':d.line((159,263,130,487),fill='#ecd18e',width=8)
    save(im,name)
actor('mira-a','#bc5368','#543245','cape')
actor('mira-a-joy','#bc5368','#543245','cape','joy')
actor('mira-a-stern','#bc5368','#543245','cape','stern')
actor('mira-a-coat','#438a9b','#543245','coat')
actor('mira-a-coat-joy','#438a9b','#543245','coat','joy')
actor('mira-b','#8b71bf','#dcd29b','hat')
actor('rowan','#659761','#9a6244','coat')
actor('sage','#dba451','#424663','hat')
# Small, deliberately too-wide raster for decoded-dimension refusal.
save(Image.new('RGB',(4097,1),'#000000'),'oversized')
manifest=[]
for path in sorted(root.glob('*.png')):
    im=Image.open(path)
    manifest.append(dict(file=path.name,width=im.width,height=im.height,format='PNG',mode=im.mode,bytes=path.stat().st_size,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),attribution='Original synthetic procedural SillyNovel test fixture; generated by generate_assets.py. No external art.'))
(root/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
